function renderService(service){
 pageTitle(service.name,service.label+' — robotik cərrahiyyənin tətbiq imkanları.');
 main.innerHTML=`<div class="wrap">${bread(service.name)}<div class="detail-header"><p class="eyebrow">ROBOTİK CƏRRAHİYYƏ · ${service.symbol}</p><h1>${service.name}</h1><p class="intro">${service.label}</p></div><div class="detail-layout"><article class="article-body"><p class="lead">${service.intro}</p><h2>Tətbiq imkanları</h2><ul class="procedure-list">${service.items.map(x=>`<li><span aria-hidden="true">+</span>${x}</li>`).join('')}</ul><div class="clinical-note"><strong>Sizə uyğun yanaşma necə seçilir?</strong><p>Əməliyyatın növü, diaqnoz, xəstəliyin mərhələsi və ümumi sağlamlıq vəziyyəti birlikdə qiymətləndirilir. Robotik üsul bütün pasiyentlər üçün uyğun olmaya bilər. Konkret prosedurun mövcudluğu konsultasiyada dəqiqləşdirilir.</p></div>${service.slug==='urologiya'?`<a class="inline-doctor" href="/hekim/emin-memmedov/"><span><strong>Uzm. Dr. Emin Məmmədov</strong><small>Uroloq-androloq · Həkim profilinə bax</small></span><span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></span></a>`:''}<a class="text-link" href="/xidmetler/"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 5-7 7 7 7"/></svg> Bütün istiqamətlərə qayıt</a></article>${supportCard(service.slug)}</div></div>${contactHTML()}`;
}
function renderAbout(){pageTitle('Haqqımızda');main.innerHTML=`<div class="wrap">${bread('Haqqımızda')}<div class="detail-header"><p class="eyebrow">EGE HOSPITAL</p><h1>Robotik Cərrahiyyə<br>Mərkəzi</h1><p class="intro">Müasir texnologiya və cərrahın peşəkar təcrübəsi bir arada.</p></div><div class="detail-layout"><article class="article-body"><p class="lead">Ege Hospital Robotik Cərrahiyyə Mərkəzi müasir cərrahiyyənin imkanlarını robotik texnologiya ilə birləşdirən ixtisaslaşmış mərkəzdir.</p><h2>Yanaşmamız</h2><p>Mərkəzdə texnoloji imkanlar cərrahların təcrübəsi və multidissiplinar tibbi yanaşma ilə birləşdirilir. Müalicə seçimi hər pasiyentin diaqnozu və tibbi göstərişləri əsasında fərdi şəkildə qiymətləndirilir.</p><p>Robotik sistem cərrahın nəzarət etdiyi texnoloji platformadır. Əsas dəyər texnologiyanın cərrahın bilik, təcrübə və qərarvermə imkanları ilə birləşməsindədir.</p><h2>Məqsədimiz</h2><p>Azərbaycanda müasir cərrahiyyənin inkişafına töhfə vermək, pasiyent yönümlü xidmət təqdim etmək, robotik cərrahiyyə sahəsində bilik və təcrübə mübadiləsini dəstəkləmək.</p><h2>Fəaliyyət istiqamətləri</h2><p>Urologiya, ginekologiya, ümumi və kolorektal cərrahiyyə, torakal cərrahiyyə və seçilmiş ürək-damar müdaxilələri haqqında məlumatla xidmət səhifələrində tanış ola bilərsiniz.</p><a href="/xidmetler/" class="text-link">Xidmətləri nəzərdən keçirin <svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a></article>${supportCard()}</div></div>${contactHTML()}`}
function renderTechnology(){pageTitle('Robotik cərrahiyyə nədir?');main.innerHTML=`<div class="wrap">${bread('Robotik cərrahiyyə')}<div class="detail-header"><p class="eyebrow">TEXNOLOGİYANI TANIYIN</p><h1>Cərrahın nəzarəti.<br>Robotik dəqiqlik.</h1><p class="intro">Minimal invaziv cərrahiyyənin inkişaf etmiş istiqaməti.</p></div><div class="detail-layout"><article class="article-body"><p class="lead">Cərrah xüsusi konsoldan sistemi idarə edir. Robotik sistem onun hərəkətlərini incə və çevik cərrahi alətlərə ötürür.</p><img class="technology-image" src="/assets/robotic-room.png" width="448" height="465" alt="Robotik cərrahiyyə sisteminin illüstrativ təsviri"><h2>Sistem necə işləyir?</h2><p>Böyüdülmüş üçölçülü görüntü əməliyyat sahəsini daha detallı görməyə kömək edir. Cərrah konsolda alətlərin hərəkətinə və əməliyyatın gedişinə nəzarət edir.</p><h2>Əsas imkanlar</h2><ul class="procedure-list"><li><span>+</span>Əməliyyat sahəsinin böyüdülmüş, üçölçülü görüntüsü</li><li><span>+</span>Məhdud anatomik sahələrdə çevik alətlərlə işləmək imkanı</li><li><span>+</span>Cərrahın hərəkətlərinin dəqiq ötürülməsi</li><li><span>+</span>Uyğun əməliyyatlarda daha kiçik kəsiklər</li></ul><div class="clinical-note"><strong>Nəticə fərdi olaraq dəyişir.</strong><p>Üstünlüklər və risklər əməliyyatın növündən və pasiyentin xüsusiyyətlərindən asılıdır. Müalicə variantları həkim konsultasiyasında müzakirə edilməlidir.</p></div><button class="button primary" data-video>Rəsmi videoya bax<span class="arrow" aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 5 11 7-11 7V5Z"/></svg></span></button><h2 id="suallar" style="scroll-margin-top:24px">Tez-tez verilən suallar</h2><div class="faq-list">${faqHTML()}</div></article>${supportCard()}</div></div>`}
function renderDoctor(){pageTitle('Uzm. Dr. Emin Məmmədov','Uroloq-androloq Emin Məmmədov haqqında məlumat və konsultasiya əlaqəsi.');main.innerHTML=`<div class="wrap">${bread('Həkimimiz')}<section class="doctor-profile"><div><p class="eyebrow">HƏKİM PROFİLİ</p><h1>Uzm. Dr.<br>Emin Məmmədov</h1><p class="profile-specialty">Uroloq-androloq</p><p>Tibb üzrə fəlsəfə doktoru</p><div class="doctor-credentials"><span>Çukurova Universiteti</span><span>FEBU</span></div>${cta('Urologiyada tətbiqi','/xidmetler/urologiya/')}</div></section><div class="detail-layout"><article class="article-body"><h2>Təhsil və ixtisaslaşma</h2><ul class="procedure-list"><li><span>+</span>Azərbaycan Tibb Universiteti</li><li><span>+</span>2005–2012: Çukurova Universiteti, Adana, Türkiyə — urologiya üzrə uzmanlıq</li><li><span>+</span>European Board of Urology (FEBU) diplomu</li></ul><h2>Robotik cərrahiyyə barədə konsultasiya</h2><p>Uroloji robotik müdaxilələrin tətbiq imkanları və fərdi uyğunluq həkimlə qiymətləndirilir. Əməliyyat barədə qərar müayinə və tibbi göstərişlər əsasında verilir.</p><a class="text-link" href="/xidmetler/urologiya/">Urologiyada tətbiq sahələri <svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><p class="source-note">Təhsil məlumatları: <a href="https://egehospital.az/hekimler/108-uzman-dr-emin-memmedov.html" target="_blank" rel="noopener">EGE Hospitalın rəsmi həkim profili</a>.</p></article>${supportCard('urologiya')}</div></div>${contactHTML()}`}
function renderBooking(){pageTitle('Əlaqə');main.innerHTML=contactHTML()}
function renderPrivacy(){pageTitle('Məxfilik və istifadə');main.innerHTML=`<div class="wrap narrow">${bread('Məxfilik və istifadə')}<div class="detail-header"><h1>Məxfilik<br>və istifadə</h1></div><article class="article-body"><h2>Saytın məqsədi</h2><p>Bu sayt robotik cərrahiyyə haqqında ümumi məlumat verir və EGE Hospitalın əlaqə kanallarına yönləndirir. Məzmun fərdi diaqnoz, müalicə tövsiyəsi və ya nəticə zəmanəti deyil.</p><h2>Xarici xidmətlər</h2><p>WhatsApp keçidi xarici mesajlaşma xidmətini açır. Video açıldıqda YouTube-a, xəritə keçidində Google Maps-ə qoşulursunuz. Bu xidmətlərin öz məxfilik qaydaları tətbiq olunur.</p><h2>Texniki məlumatlar</h2><p>Saytın hostinq provayderi səhifəni təqdim etmək üçün texniki bağlantı məlumatlarını emal edə bilər. Saytda istifadəçi davranışını anlamaq üçün Microsoft Clarity istifadə olunur. Səhifə baxışları, kliklər və sürüşdürmə hərəkətləri emal oluna bilər. Saytın özündə pasiyent məlumatlarını saxlayan forma yoxdur.</p><h2>Əlaqə</h2><p>Suallar üçün <a href="mailto:info@robotikcerrahiyye.az">info@robotikcerrahiyye.az</a> ünvanına və ya <a href="tel:+994125991117">+994 12 599 11 17</a> nömrəsinə müraciət edə bilərsiniz.</p></article></div>`}

if(path==='/'){
 document.querySelector('#home-content').innerHTML=homeHTML;
 document.querySelector('.visual-inner').insertAdjacentHTML('afterbegin','<img class="hero-robot" src="/assets/robotic-room.png" alt="Robotik cərrahiyyə sisteminin illüstrativ təsviri" width="448" height="465" fetchpriority="high">');
}else if(matches&&services.some(s=>s.slug===matches[1])){renderService(services.find(s=>s.slug===matches[1]));}
else if(path==='/xidmetler'){renderServices()}
else if(path==='/bloq'){renderBlog()}
else if(posts.some(p=>path==='/bloq/'+p.slug)){renderPost(posts.find(p=>path==='/bloq/'+p.slug))}
else if(path==='/haqqimizda'){renderAbout()}
else if(path==='/robotik-cerrahiyye'){renderTechnology()}
else if(path==='/hekim/emin-memmedov'){renderDoctor()}
else if(path==='/konsultasiya'){renderBooking()}
else if(path==='/mexfilik'){renderPrivacy()}
else{pageTitle('Səhifə tapılmadı');main.innerHTML=`<div class="wrap error-page"><p class="eyebrow">404</p><h1>Səhifə tapılmadı.</h1><p>Axtardığınız məlumatı ana səhifədən tapa bilərsiniz.</p>${cta('Ana səhifəyə qayıt','/')}</div>`}

const dialog=document.querySelector('#video-dialog');let videoTrigger=null;
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-video]');if(!trigger)return;videoTrigger=trigger;document.querySelector('#video-content').innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/EScQbz6EHbM?autoplay=1" title="EGE Hospital — robotik cərrahiyyə haqqında video" allow="autoplay; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><a class="small-link" href="https://www.youtube.com/watch?v=EScQbz6EHbM" target="_blank" rel="noopener">Video açılmırsa, YouTube-da izləyin <svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a>';dialog.showModal()});
document.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.querySelector('#video-content').innerHTML='';videoTrigger?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
if(location.hash){requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView())}

